        /* —— Commands 页 —— */
        'to turn a prompt into': '，把提示词变成',
        'Run it from the TUI with a target:': '在 TUI 中带目标运行它：',
        'OpenCode submits': 'OpenCode 会把',
        'as a user prompt.': '作为用户提示词提交。',
        'Put global commands in': '把全局命令放在',
