        'for new files.': '。',
        'Add YAML frontmatter when the command needs metadata. The trimmed Markdown body is always the prompt template.': '命令需要元数据时，请加上 YAML frontmatter。去除首尾空白后的 Markdown 正文始终是提示词模板。',
        'Define commands under': '请在',
