        'to hide a model from the available catalog:': '可以把模型从可用目录中隐藏：',
        'For an OpenAI-compatible model that streams reasoning in a custom assistant-message field, set': '对于在自定义助手消息字段中流式输出推理内容的 OpenAI 兼容模型，请设置',
        'OpenCode recognizes': 'OpenCode 能识别',
        ', and also accepts another provider-specific string. It reads streamed reasoning from that field and restores the field when sending prior assistant messages back to the model.': '，也接受其他提供商特定的字符串。它会从该字段读取流式推理内容，并在把之前的助手消息回传给模型时恢复该字段。',
        'OpenCode places prompt-cache breakpoints automatically on routes that are known to need them, such as Anthropic. When Claude models are served through an OpenAI-compatible proxy such as LiteLLM, OpenCode cannot tell that they need Anthropic-style': '对于已知需要提示词缓存断点的路由（例如 Anthropic），OpenCode 会自动放置断点。当 Claude 模型通过 LiteLLM 这类 OpenAI 兼容代理提供时，OpenCode 无法判断它们需要 Anthropic 风格的',
        'breakpoints. Set': '断点。请在这些 Claude 模型上设置',
        'on those Claude models:': '：',
        'OpenCode then marks the last tool definition, the system prompt, and the latest message with': '随后 OpenCode 会用',
        ", which uses the endpoint\'s default five-minute cache lifetime. Use": '标记最后一个工具定义、系统提示词与最新消息，这会使用端点默认的五分钟缓存生命周期。对于 Alibaba Model Studio 的模型，请使用',
        'for Alibaba Model Studio models, which accept the same markers but ignore them on tool definitions. Set': '，它们接受相同的标记，但会在工具定义上忽略这些标记。如果该提供商下的所有模型都接受相同格式，可以改为在提供商上设置',
        'on the provider instead when every model it serves accepts the same format.': '。',
        'OpenCode automatically discovers models from Ollama, LM Studio, and vLLM at their default local addresses. You can also configure any OpenAI-compatible server manually.': 'OpenCode 会自动从 Ollama、LM Studio 和 vLLM 的默认本地地址发现模型。你也可以手动配置任意 OpenAI 兼容服务器。',
        'With Ollama listening at': '当 Ollama 监听在',
        ', select a discovered model with the': '时，用以下',
        'provider ID:': '提供商 ID 选择已发现的模型：',
        'OpenCode refreshes the inventory in the background and reads context, vision, and tool-use capabilities from Ollama. Embedding-only models are excluded.': 'OpenCode 会在后台刷新清单，并从 Ollama 读取上下文、视觉与工具调用能力。仅用于嵌入的模型会被排除。',
        "For another host or port, set Ollama\'s OpenAI-compatible URL. Discovery still uses the native Ollama API at the same path prefix:": '如果使用其他主机或端口，请设置 Ollama 的 OpenAI 兼容 URL。发现过程仍会在相同路径前缀下使用原生 Ollama API：',
