        'OpenCode refreshes the inventory in the background and reads context, vision, and tool-use capabilities from LM Studio. Embedding models are excluded.': 'OpenCode 会在后台刷新清单，并从 LM Studio 读取上下文、视觉与工具调用能力。嵌入模型会被排除。',
        'For another host or port, set the OpenAI-compatible URL. Models are still discovered automatically:': '如果使用其他主机或端口，请设置 OpenAI 兼容 URL。模型仍会被自动发现：',
        'when LM Studio authentication is disabled.': '前提是 LM Studio 的认证已关闭。',
