        'as the context limit, and includes only model cards owned by': '作为上下文上限，并且只包含属于以下所有者的模型卡',
        'Discovered models advertise text input and output, but not vision or tools. vLLM enables tool calling with server flags such as': '发现的模型会声明文本输入与输出，但不会声明视觉或工具。vLLM 通过诸如',
        ', which discovery does not report.': '这样的服务端开关启用工具调用，而发现过程不会报告这一点。',
        'For another endpoint or an authenticated server, set its OpenAI-compatible URL:': '对于其他端点或需要认证的服务器，请设置其 OpenAI 兼容 URL：',
        'when authentication is disabled.': '前提是认证已关闭。',
        'Path-prefixed proxies are supported. For example,': '支持带路径前缀的代理。例如',
        'checks': '会检查',
        'and discovers': '并发现',
        "For another OpenAI-compatible server, define its provider package, endpoint, and at least one model:": '对于其他 OpenAI 兼容服务器，请定义其提供商包、端点以及至少一个模型：',
        "Use the server\'s real model name, limits, input and output types, and tool support. OpenCode cannot detect whether the custom-model fallback values are accurate. If the endpoint requires a key, add": '请使用服务器真实的模型名、上限、输入/输出类型与工具支持。OpenCode 无法探测自定义模型的回退值是否准确。若端点需要密钥，请把',
