        'when present.': '（存在时）。',
        'Casing': '大小写',
        'Provider and model IDs are case-sensitive.': '提供商与模型 ID 区分大小写。',
        'Use catalog IDs rather than provider display names. Root, agent, and command': '请使用目录 ID，而不是提供商的显示名称。根级、智能体与命令中的',
        'fields accept the string form above or an expanded object:': '字段接受上面的字符串形式，或展开的对象形式：',
        'The expanded form is useful for generated or programmatic configuration.': '展开形式适合生成式或程序化配置。',
        'Keep these rules in mind when configuring models:': '配置模型时请注意以下规则：',
        'A selector object uses': '选择器对象使用',
        '; a provider catalog entry uses': '；提供商目录条目使用',
        'for the ID sent to the provider.': '作为发送给提供商的 ID。',
        'Although the root selection shape accepts a variant, the V2 catalog default does not retain it. Select variants for a session, run, agent, or command instead.': '虽然根级选择结构接受变体，但 V2 的目录默认值不会保留它。请改为在会话、运行、智能体或命令中选择变体。',
        'Model options are provider-specific. Another provider package may ignore or reject them.': '模型选项是提供商特定的，其他提供商包可能忽略或拒绝它们。',
        'Catalog data, credentials, and configuration are location-scoped. A model available in one project may be unavailable in another.': '目录数据、凭据与配置都以位置为作用域。某个项目可用的模型在另一个项目中可能不可用。',
        'Configuration files normally reload automatically. A model request already in progress keeps the settings it started with.': '配置文件通常会重新加载。已经进行中的模型请求会沿用开始时的设置。',
