        'values. See': '值。参见',
        'V2 groups the retained-context token budget under': 'V2 把保留上下文的 token 预算归到',
        'and gives the reserve a clearer name:': '下，并给保留量起了更清晰的名称：',
        'keeps its name. V2 has no native': '保持原名。V2 没有原生的',
        'field; both legacy fields are ignored with a warning. Recent context is retained by token budget instead. See': '字段；两个旧字段都会被忽略并给出警告。近期上下文改为按 token 预算保留。参见',
        'V1 separates extra skill paths and URLs. V2 combines both into one ordered array:': 'V1 把额外的技能路径与 URL 分开。V2 把两者合并为一个有序数组：',
        'Existing skill files and automatic': '现有的技能文件与自动',
        'discovery do not change. See': '发现方式保持不变。参见',
