        'when connecting Azure.': '来连接 Azure。',
        'Enter the resource name when connecting if it is not already supplied by configuration or the environment. A resource name saved with a connection takes precedence over configuration; connect again to change it.': '如果配置或环境尚未提供资源名，请在连接时输入。随连接保存的资源名优先于配置；要修改请重新连接。',
        'Azure CLI connections use the account selected in the Azure CLI. For a resource in another tenant or subscription, select both explicitly.': 'Azure CLI 连接使用 Azure CLI 中选定的账户。若资源位于其他租户或订阅，请显式指定两者。',
