        'variable also works.': '变量同样有效。',
        'Azure serves a model only through a deployment, so OpenCode lists the deployments of your resource and shows those instead of the whole Azure catalog. The list loads in the background after startup, after connecting, and after switching accounts. To pick up a deployment added later, restart OpenCode or connect again.': 'Azure 只能通过部署提供模型，因此 OpenCode 会列出你资源下的部署，并用它们代替整个 Azure 目录。该列表会在启动后、连接后以及切换账户后在后台加载。要识别之后新增的部署，请重启 OpenCode 或重新连接。',
        'Until the list loads for a connection, or if it fails, the whole catalog stays available.': '在某个连接的列表加载完成之前，或加载失败时，整个目录仍然可用。',
        'A failed reload for the same connection keeps its last complete inventory.': '同一连接重新加载失败时，会保留上次完整的清单。',
        'Switching accounts never shows the previous account\'s inventory; the new account starts from the whole catalog.': '切换账户时绝不会显示上一个账户的清单；新账户从整个目录开始。',
        'Deployments inherit limits, costs, and capabilities from their catalog models.': '部署会继承其目录模型的限制、费用与能力。',
        'Deployment names are their model IDs, in lowercase because Azure ignores case in names, for example': '部署名就是它们的模型 ID，全小写（因为 Azure 忽略名称大小写），例如',
