        'OpenCode matches a deployment to the catalog by the model it deploys, or by its name when Azure spells the model differently, as with': 'OpenCode 按部署所使用的模型与目录匹配；当 Azure 的模型写法不同时（例如',
        'for GPT-4 Turbo. A deployment named after another model, such as': '对应 GPT-4 Turbo），则按部署名匹配。以另一个模型命名的部署，例如',
        'deploying': '部署了',
        ', shows that model\'s name, limits, and costs.': '，会显示那个模型的名称、限制与费用。',
        'With the Azure CLI, OpenCode lists deployments through the Azure management API, which needs read access to the resource. If that fails, and always with an API key, it uses the resource\'s legacy deployment inventory. Discovery reads every page before publishing the list. A custom': '使用 Azure CLI 时，OpenCode 通过 Azure 管理 API 列出部署，这需要对资源的读权限。如果失败，以及在使用 API 密钥的情况下，它会使用资源的旧版部署清单。发现过程会读完所有分页后再发布列表。自定义的',
        'keeps the catalog.': '会保留目录。',
        'Configure a deployment explicitly when its model is not in the catalog, such as a fine-tuned model, or to map a model ID to a deployment yourself. OpenCode logs a warning naming such deployments. Explicitly configured models are always kept.': '当部署所用的模型不在目录中（例如微调模型），或你想自行把模型 ID 映射到部署时，请显式配置该部署。OpenCode 会在日志中警告并列出这类部署。显式配置的模型始终保留。',
        'Your identity needs one of these roles:': '你的身份需要具备以下角色之一：',
