        'for other Foundry models.': '（用于其他 Foundry 模型）。',
        'If a request uses a token from the wrong tenant, sign in again with the required tenant.': '如果请求使用了错误租户的 token，请用所需租户重新登录。',
        'Amazon Bedrock uses the AWS default credential chain. A named AWS profile is the simplest durable setup; OpenCode also recognizes access-key environments, web identity, and container credentials.': 'Amazon Bedrock 使用 AWS 默认凭据链。具名 AWS profile 是最简单的持久化配置；OpenCode 也能识别访问密钥环境变量、Web 身份与容器凭据。',
        'Select the profile and region in provider settings. A configured': '在提供商设置中选择 profile 与区域。已配置的',
