        'Google Vertex uses Application Default Credentials (ADC) and needs a project before its models become available. Create local ADC, then set the project and location in provider settings.': 'Google Vertex 使用应用默认凭据（ADC），且必须先有项目，其模型才可用。请先创建本地 ADC，然后在提供商设置中设置项目与位置。',
