        'provider ID is unavailable in V2.': '提供商 ID 在 V2 中不可用。',
        'GitHub Copilot supports device OAuth rather than manual API-key entry. Connect': 'GitHub Copilot 支持设备 OAuth，而不是手动输入 API 密钥。请连接',
