        ', choose GitHub.com or GitHub Enterprise, finish the device flow, then open': '，选择 GitHub.com 或 GitHub Enterprise，完成设备码流程，然后打开',
        'For GitHub Enterprise, enter the deployment URL or domain when prompted. OpenCode uses a Copilot API endpoint returned by GitHub when available; otherwise it derives the endpoint from the enterprise domain.': '对于 GitHub Enterprise，请在提示时输入部署 URL 或域名。GitHub 返回 Copilot API 端点时 OpenCode 会使用它；否则会从企业域名推导端点。',
        'The connected account needs Copilot Chat access. If GitHub reports no entitlement, sign up for Copilot Free or ask the organization to assign a Copilot seat, then connect again. OpenCode fetches the account\'s current model list after login and whenever the active Copilot account changes.': '连接的账户需要具备 Copilot Chat 权限。如果 GitHub 报告无相应权益，请注册 Copilot Free 或请组织分配 Copilot 席位，然后重新连接。OpenCode 会在登录后以及活动 Copilot 账户变化时获取该账户当前的模型列表。',
