        'to the OpenCode server or connect an OpenRouter account, then refer to models with the full OpenRouter model ID after the provider prefix.': '给 OpenCode 服务端，或连接一个 OpenRouter 账户，然后在提供商前缀之后用完整的 OpenRouter 模型 ID 引用模型。',
        'Keep the native OpenRouter package when overriding its endpoint or routing through an OpenRouter-compatible gateway. This preserves OpenRouter request and reasoning behavior.': '覆盖其端点或经 OpenRouter 兼容网关路由时，请保留原生 OpenRouter 包。这样才能保留 OpenRouter 的请求与推理行为。',
        'For a gateway that exposes an OpenAI-compatible API but has its own model inventory, define a custom provider instead. The configuration key becomes the provider prefix and each': '对于提供 OpenAI 兼容 API 但拥有自己模型清单的网关，请改为定义自定义提供商。配置键会成为提供商前缀，而每个',
        'key becomes a selectable model ID.': '键会成为可选的模型 ID。',
