        'Vertex does not appear': 'Vertex 不出现',
        'Set a resolvable project in provider settings or a supported project variable. ADC alone does not activate the provider.': '请在提供商设置或受支持的项目变量中设置可解析的项目。仅靠 ADC 不会激活该提供商。',
        'Bedrock does not appear': 'Bedrock 不出现',
