        'Confirm the active OAuth account has Copilot Chat access. A failed model sync is logged as': '请确认当前 OAuth 账户具有 Copilot Chat 权限。模型同步失败会记录为',
        'V2 rejects the retired provider IDs with a direct replacement. Use': 'V2 会拒绝已停用的提供商 ID，并给出直接替代。请用',
        'OpenAI, xAI, and supported Azure Responses models can keep one WebSocket connection open per session. Consecutive steps reuse the unchanged request prefix and only send content added since the previous response, reducing uploads in long sessions.': 'OpenAI、xAI 以及受支持的 Azure Responses 模型可以为每个会话保持一条 WebSocket 连接。连续步骤会复用未变化的请求前缀，只发送自上次响应以来新增的内容，从而减少长会话中的上传量。',
        'WebSocket behavior follows these rules:': 'WebSocket 行为遵循以下规则：',
        'Built-in providers opt supported routes in according to their own policy.': '内置提供商会按其自身策略选择启用受支持的路由。',
        'enables it;': '启用它；',
