        'on a route without a WebSocket channel logs a warning and falls back to HTTP.': '在不支持 WebSocket 通道的路由上是无效的，会记录警告并回退到 HTTP。',
        'OpenAI provider compaction uses the same connection.': 'OpenAI 提供商的压缩使用同一连接。',
